/**
 * Form indexes of the Greek adapter: attested or listed written forms → the analyses a source gives them. The same design as
 * the Hebrew one (src/adapters/hebrew/index-store.ts), with Greek keys.
 *
 * Indexes, all GENERATED by scripts:
 *   morphgnt-sblgnt    every word of the Greek New Testament as MorphGNT reads it (scripts/el-build-koine.mts, from the Biblia
 *                      app's data): period el-koi. A reading here is the source's reading of that very word.
 *   kaikki-grc-tables  the inflection tables and alternative forms of the Wiktionary Ancient Greek entries (scripts/el-build-ancient.mts):
 *                      the table header names the dialect (Attic by default; "Epic aorist", "Ionic declension-3", "Koine declension-2" …),
 *                      so a row's period is read from its code; lemma-level labels (Epic, Koine …) are on the lemma row.
 *   kaikki-el-tables   the tables of the Wiktionary Modern Greek entries (scripts/el-build-modern.mts): period el-mod.
 *
 * Keys: `elKey(form)` (text.ts: NFC, lower case, grave → acute, polytonic marks kept). `bare` maps a diacritic-free spelling to
 * the keys that have it, so a monotonic or unaccented query reaches the polytonic forms (and the other way round).
 */
import { bare } from './text';

/** [headword, short gloss, part of speech (UPOS), token count in the source, transliteration?, period labels ("el-koi,el-hom")?, Septuagint count?] */
export type ElLemmaRow = [headword: string, gloss: string, pos: string, count: number, translit?: string, labels?: string, lxx?: number];
/** [lemma id, the source's code ("N-|----NSM-" for MorphGNT; "table:Epic aorist|active|indicative|…" for a kaikki row), count] */
export type ElFormRow = [lemma: string, code: string, count: number];

export interface GreekFormIndex {
  schema: 1;
  id: 'morphgnt-sblgnt' | 'kaikki-grc-tables' | 'kaikki-el-tables' | string;
  codes: 'morphgnt' | 'kaikki-tags';
  /** The default period of the index's readings; a kaikki-grc row's table header may name another (Epic, Ionic, Koine …). */
  period: 'el-koi' | 'el-att' | 'el-mod';
  /** A SHARD of a larger index (scripts/el-shard-ancient.mts): the prefix of the bare letters its keys share; shards of one id are installed side by side. */
  shard?: string;
  source: { label: string; licence: string; url: string; retrieved?: string; note?: string };
  built: string;
  lemmas: Record<string, ElLemmaRow>;
  forms: Record<string, ElFormRow[]>;
  /** bare spelling → keys (only where at least one key differs from the bare spelling) */
  bare: Record<string, string[]>;
  /**
   * Cross-period links the source states: for an Ancient Greek lemma, its Modern Greek descendants ("Greek: λόγος" under
   * Descendants); for a Modern lemma, the Ancient Greek word it is inherited from (the etymology's "inh" template). Lemma id → words.
   */
  links?: Record<string, string[]>;
  stats?: Record<string, number>;
}

export interface ElIndexHit { index: GreekFormIndex; key: string; row: ElFormRow; viaBare: boolean }

const INSTALLED = new Map<string, GreekFormIndex>();
const storeKey = (id: string, shard?: string): string => (shard ? `${id}#${shard}` : id);

/** Installs an index, or one shard of one (keyed by id and shard, so the shards of an id sit side by side); re-installing replaces. */
export function installGreekIndex(idx: GreekFormIndex): void { INSTALLED.set(storeKey(idx.id, idx.shard), idx); }
export function uninstallGreekIndex(id: string, shard?: string): boolean { return INSTALLED.delete(storeKey(id, shard)); }
export function installedGreekIndexes(): GreekFormIndex[] { return [...INSTALLED.values()]; }
/** Forgets every installed index (or shard) for which `keep(id, shard)` is not true. */
export function resetGreekIndexes(keep?: (id: string, shard?: string) => boolean): void {
  for (const [k, idx] of [...INSTALLED.entries()]) if (!keep?.(idx.id, idx.shard)) INSTALLED.delete(k);
}

/**
 * Readings of a key across the installed indexes, most frequent first. The bare map is consulted when the key itself has no row
 * (a monotonic spelling of a polytonic form, a word typed without accents): every form with the same letters contributes.
 */
export function lookupGreekForm(key: string): ElIndexHit[] {
  const out: ElIndexHit[] = [];
  const b = bare(key);
  for (const index of INSTALLED.values()) {
    const direct = index.forms[key];
    if (direct) for (const row of direct) out.push({ index, key, row, viaBare: false });
  }
  if (!out.length) {
    for (const index of INSTALLED.values()) {
      for (const k of index.bare[b] ?? []) {
        if (k === key) continue;
        for (const row of index.forms[k] ?? []) out.push({ index, key: k, row, viaBare: true });
      }
      // the key may itself be a bare spelling that is also a form (unaccented monosyllables)
      if (b !== key && index.forms[b]) for (const row of index.forms[b]) out.push({ index, key: b, row, viaBare: true });
    }
  }
  return out.sort((a, c) => c.row[2] - a.row[2]);
}

export function lookupGreekLemma(lemmaId: string, index?: GreekFormIndex): ElLemmaRow | undefined {
  if (index) return index.lemmas[lemmaId];
  for (const idx of INSTALLED.values()) { const r = idx.lemmas[lemmaId]; if (r) return r; }
  return undefined;
}
